-- 6.0.1 protocol item API parameter completion
UPDATE cfg_modbus_point_item item
SET register_area_ref_id = CASE fc.code
    WHEN 'READ_COILS' THEN ref_code_id('MODBUS_REGISTER_AREA','COIL')
    WHEN 'READ_DISCRETE_INPUTS' THEN ref_code_id('MODBUS_REGISTER_AREA','DISCRETE_INPUT')
    WHEN 'READ_INPUT_REGISTERS' THEN ref_code_id('MODBUS_REGISTER_AREA','INPUT_REGISTER')
    ELSE ref_code_id('MODBUS_REGISTER_AREA','HOLDING_REGISTER')
END,
bit_offset = CASE WHEN dt.code = 'BOOL' THEN 0 ELSE NULL END
FROM ref_code fc, ref_code dt
WHERE fc.ref_code_id = item.function_code_ref_id
  AND dt.ref_code_id = item.protocol_data_type_ref_id;

UPDATE cfg_iec101_point_item item
SET cause_of_transmission_ref_id = ref_code_id('IEC101_COT','CYCLIC'),
    quality_descriptor_enabled = TRUE;

UPDATE cfg_iec104_point_item item
SET cause_of_transmission_ref_id = ref_code_id('IEC104_COT','CYCLIC'),
    quality_descriptor_enabled = TRUE,
    time_tag_enabled = TRUE;

UPDATE cfg_iec61850_mms_point_item item
SET logical_device = split_part(object_reference, '/', 1),
    logical_node = split_part(split_part(object_reference, '/', 2), '.', 1),
    data_object = split_part(split_part(object_reference, '.', 2), '.', 1),
    data_attribute = data_attribute_path;

UPDATE cfg_iec61850_goose_point_item item
SET cdc_ref_id = ref_code_id('IEC61850_CDC','SPS'),
    btype_ref_id = ref_code_id('PROTOCOL_DATA_TYPE','BOOL');

UPDATE cfg_iec61850_sv_point_item item
SET phase_ref_id = CASE ((sample_index - 1) % 3)
        WHEN 0 THEN ref_code_id('PHASE','A')
        WHEN 1 THEN ref_code_id('PHASE','B')
        ELSE ref_code_id('PHASE','C')
    END,
    quantity_ref_id = CASE WHEN sample_index % 2 = 0 THEN ref_code_id('SV_QUANTITY','VOLTAGE') ELSE ref_code_id('SV_QUANTITY','CURRENT') END,
    cdc_ref_id = ref_code_id('IEC61850_CDC','MV'),
    btype_ref_id = ref_code_id('PROTOCOL_DATA_TYPE','FLOAT32');

UPDATE cfg_opcua_point_item
SET namespace_index = 2;



UPDATE cfg_http_rest_point_item
SET query_param_path = '$.query';

-- 6.1 point item value domain completion and validation
-- Rule: every cfg_xxx_point_item must declare either a numeric engineering range or an allowed_values list.
-- BOOL points use allowed_values='0,1'; all other sample points use a broad engineering range.
DO $$
DECLARE
    t TEXT;
    tables TEXT[] := ARRAY[
        'cfg_modbus_point_item','cfg_iec101_point_item','cfg_iec104_point_item','cfg_iec61850_mms_point_item',
        'cfg_iec61850_goose_point_item','cfg_iec61850_sv_point_item','cfg_opcua_point_item','cfg_mqtt_point_item',
        'cfg_http_rest_point_item','cfg_ads_point_item'
    ];
    null_count BIGINT;
BEGIN
    FOREACH t IN ARRAY tables LOOP
        EXECUTE format(
            'UPDATE whale.%I
             SET allowed_values = ''0,1'', value_min = NULL, value_max = NULL
             WHERE protocol_data_type_ref_id = whale.ref_code_id(''PROTOCOL_DATA_TYPE'',''BOOL'')', t);

        EXECUTE format(
            'UPDATE whale.%I
             SET value_min = -1000000, value_max = 1000000, allowed_values = NULL
             WHERE value_min IS NULL AND value_max IS NULL AND allowed_values IS NULL', t);

        EXECUTE format(
            'SELECT count(*) FROM whale.%I
              WHERE value_min IS NULL AND value_max IS NULL AND allowed_values IS NULL', t)
        INTO null_count;

        IF null_count > 0 THEN
            RAISE EXCEPTION 'Point item value domain missing in %, count=%', t, null_count;
        END IF;
    END LOOP;
END $$;

